export const SessionBudgetSettings = zod
	.object({
		budget: zod
			.number()
			.optional()
			.describe(
				'\n        This budget is shared across all agents in the session and can be used by any agent configured to consume the shared budget.\n        \n        The value is specified in micro cents. $1.00 is 100000000 and $0.01 is 1000000.\")    \n        '
			),
		exhaustionBehavior: zod
			.union([
				zod
					.object({
						type: zod.enum(['ignore'])
					})
					.describe(
						"The exhaustion of the session's budget will be ignored.  This has a high chance of overclaiming."
					),
				zod
					.object({
						type: zod.enum(['kill_agent']),
						minimum: zod
							.number()
							.describe(
								'The minimum value, specified in micro cents. $1.00 is 100000000 and $0.01 is 1000000.'
							),
						force: zod
							.boolean()
							.describe(
								'If this is true, when an agent claims from the session budget that is below the minimum, the agent will be killed immediately.  If this is false, the agent will only be killed if the agent requests for automatic closing.'
							),
						forceDelay: zod
							.string()
							.optional()
							.describe(
								'If force killing is enabled, it will be delayed by this amount before the agent is killed.  If this delay is too low the agent may be killed before it handles to response to a claim'
							)
					})
					.describe(
						'Once the session budget drops below the specified minimum, agents that claim for it will be killed.  The higher the minimum is the lower the chance of overclaiming.'
					),
				zod
					.object({
						type: zod.enum(['kill_session']),
						minimum: zod
							.number()
							.describe(
								'The minimum value, specified in micro cents. $1.00 is 100000000 and $0.01 is 1000000.'
							),
						delay: zod
							.string()
							.optional()
							.describe(
								'The delay before the session is killed.  If this delay is too low, the agent whose claim triggered this may be killed before it receives the response to that claim'
							)
					})
					.describe(
						'Once the session budget drops below the specified minimum, agents that claim for it will trigger the session to be killed.  The higher the minimum is the lower the chance of overclaiming.'
					)
			])
			.optional()
			.describe(
				"\n        The behavior for agents consuming from this budget after it has been exhausted.  Note that this behavior\n        only applies to agents that consume from the session budgets. Agents that have their own budget will first \n        perform behaviors described by the agent's own budget settings.\n        "
			)
	})
	.describe('Budgets settings for this session.  Budgets are consumed by agents in the session.');

